#!/usr/bin/env node
/**
 * Generates one TypeScript module per OpenAPI spec the console consumes.
 *
 * Types only, no client. Every spec has zero `operationId`s, so a method-name
 * generator (orval, openapi-generator, kubb) would emit autogenerated garbage names
 * for all 68 operations -- and we want to own the Axios layer anyway, because the
 * idempotency and error interceptors live there.
 *
 * There is no aggregate spec on this platform (15 files, no springdoc endpoint), so
 * there is no merge step. 14 of the 15 `$ref` into openapi-common.yaml with relative
 * paths, which openapi-typescript resolves from the spec's own directory.
 *
 * NOTE: the previous portal's version of this script listed only 11 specs and
 * silently skipped distribution, finaccounting, regreporting and reinsurance --
 * exactly the four a staff console needs most. This one derives the list from the
 * directory and fails if a spec is unreadable, so a spec cannot go missing quietly.
 */
import { execFileSync } from 'node:child_process';
import { mkdirSync, readdirSync, writeFileSync, rmSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const SPEC_DIR = resolve(here, '../../backend/api/openapi');
const OUT_DIR = resolve(here, '../src/types/api');
// Invoke the locally installed CLI with this same node binary. Going through `npx`
// spawns npx.cmd on Windows, which spawnSync rejects with EINVAL unless a shell is
// involved -- and a shell here would mean quoting paths that contain spaces.
const CLI = resolve(here, '../node_modules/openapi-typescript/bin/cli.js');

const specs = readdirSync(SPEC_DIR)
  .filter((f) => f.startsWith('openapi-') && f.endsWith('.yaml'))
  .sort();

if (specs.length === 0) {
  console.error(`No specs found in ${SPEC_DIR}`);
  process.exit(1);
}

// Regenerate from scratch: a spec deleted upstream should not leave a stale module
// behind for application code to keep importing.
rmSync(OUT_DIR, { recursive: true, force: true });
mkdirSync(OUT_DIR, { recursive: true });

const generated = [];
for (const spec of specs) {
  const name = spec.replace(/^openapi-/, '').replace(/\.yaml$/, '');
  const out = join(OUT_DIR, `${name}.ts`);
  process.stdout.write(`  ${spec} -> src/types/api/${name}.ts\n`);
  execFileSync(process.execPath, [CLI, join(SPEC_DIR, spec), '-o', out], {
    stdio: ['ignore', 'ignore', 'inherit'],
  });
  generated.push(name);
}

// A barrel so application code imports from one place and the module-per-spec
// layout stays an implementation detail.
const barrel = [
  '// GENERATED by scripts/generate-api-types.mjs -- do not edit.',
  `// Source: backend/api/openapi/ (${generated.length} specs)`,
  '',
  ...generated.map((n) => `export type { components as ${camel(n)}Components, paths as ${camel(n)}Paths } from './${n}';`),
  '',
].join('\n');
writeFileSync(join(OUT_DIR, 'index.ts'), barrel);

console.log(`\n${generated.length} spec(s) generated into src/types/api/`);

function camel(s) {
  return s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}
